import React, { useState } from "react";
import { 
  Box, 
  Typography, 
  Button, 
  TextField, 
  Table, 
  TableBody, 
  TableCell, 
  TableContainer, 
  TableHead, 
  TableRow, 
  Paper, 
  Dialog, 
  DialogTitle, 
  DialogContent, 
  DialogActions,
  IconButton,
  Tooltip
} from "@mui/material";
import { Add, Edit, Delete } from "@mui/icons-material";

const ManageElections = () => {
  const [elections, setElections] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [currentElection, setCurrentElection] = useState({ id: null, name: "", startDate: "", endDate: "" });

  const handleOpenDialog = (election = { id: null, name: "", startDate: "", endDate: "" }) => {
    setCurrentElection(election);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setCurrentElection({ id: null, name: "", startDate: "", endDate: "" });
  };

  const handleSaveElection = () => {
    if (currentElection.id === null) {
      // Add new election
      setElections([...elections, { ...currentElection, id: elections.length + 1 }]);
    } else {
      // Update existing election
      setElections(elections.map((election) =>
        election.id === currentElection.id ? currentElection : election
      ));
    }
    handleCloseDialog();
  };

  const handleDeleteElection = (id) => {
    setElections(elections.filter((election) => election.id !== id));
  };

  return (
    <Box sx={{ p: 4, backgroundColor: "rgba(100, 200, 225, 0.3)", minHeight: "100vh" }}>
      {/* Centered Heading and Button */}
      <Box sx={{ textAlign: "center", mb: 4 }}>
        <Typography variant="h4" fontWeight="bold" mb={2}>
          Manage Elections
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => handleOpenDialog()}
          sx={{ 
            bgcolor: "#28a745", 
            color: "white", 
            "&:hover": { bgcolor: "#218838" } 
          }}
        >
          Create New Election
        </Button>
      </Box>

      {/* Lengthened Table */}
      <TableContainer 
        component={Paper} 
        sx={{ 
          borderRadius: "16px", 
          boxShadow: 4, 
          maxHeight: "60vh", // Adjust height here
          overflow: "auto" 
        }}
      >
        <Table>
          <TableHead>
            <TableRow sx={{ backgroundColor: "#007bff" }}>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Election Name</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Start Date</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>End Date</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {elections.map((election) => (
              <TableRow key={election.id} sx={{ "&:hover": { backgroundColor: "rgba(0, 123, 255, 0.1)" } }}>
                <TableCell>{election.name}</TableCell>
                <TableCell>{election.startDate}</TableCell>
                <TableCell>{election.endDate}</TableCell>
                <TableCell>
                  <Tooltip title="Edit Election">
                    <IconButton
                      onClick={() => handleOpenDialog(election)}
                      sx={{ color: "#007bff", "&:hover": { color: "#0056b3" } }}
                    >
                      <Edit />
                    </IconButton>
                  </Tooltip>
                  <Tooltip title="Delete Election">
                    <IconButton
                      onClick={() => handleDeleteElection(election.id)}
                      sx={{ color: "#dc3545", "&:hover": { color: "#a71d2a" } }}
                    >
                      <Delete />
                    </IconButton>
                  </Tooltip>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Dialog for adding/editing elections */}
      <Dialog open={openDialog} onClose={handleCloseDialog} fullWidth maxWidth="sm">
        <DialogTitle sx={{ backgroundColor: "#007bff", color: "white" }}>
          {currentElection.id ? "Edit Election" : "Create New Election"}
        </DialogTitle>
        <DialogContent sx={{ mt: 3 }}>
          <TextField
            label="Election Name"
            fullWidth
            value={currentElection.name}
            onChange={(e) => setCurrentElection({ ...currentElection, name: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="Start Date"
            type="date"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={currentElection.startDate}
            onChange={(e) => setCurrentElection({ ...currentElection, startDate: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="End Date"
            type="date"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={currentElection.endDate}
            onChange={(e) => setCurrentElection({ ...currentElection, endDate: e.target.value })}
          />
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={handleCloseDialog} 
            sx={{ color: "#6c757d", "&:hover": { color: "#5a6268" } }}
          >
            Cancel
          </Button>
          <Button 
            onClick={handleSaveElection} 
            variant="contained"
            sx={{ bgcolor: "#28a745", color: "white", "&:hover": { bgcolor: "#218838" } }}
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ManageElections;
